{
  "outcome": "supplier dispute",
  "reasoning": "The customer claims a double charge on the same invoice, which is a financial issue rather than a product defect or warranty claim. This requires resolution with finance or accounting, not an RMA.",
  "requiresFollowup": true,
  "followupQuestions": [
    "Can you provide the invoice number and a copy of the billing statement showing the duplicate charge?",
    "Have you contacted finance or billing department about this issue previously?"
  ],
  "action": "flag_finance_dispute"
}

{
  "outcome": "Valid warranty claim for wrong item received",
  "reasoning": "The customer reports receiving an item where the SKU on the box doesn't match the SKU ordered, indicating a fulfillment error by the supplier.",
  "requiresFollowup": true,
  "followupQuestions": [
    "Can you please provide a photo of the item and the box showing the SKU and packaging?",
    "Did you receive the correct item physically but with wrong SKU labeling, or was the entire item incorrect?"
  ],
  "action": "request_photos"
}

{
  "outcome": "Rejected due to warranty expiration",
  "reasoning": "The order is 14 months old, which typically exceeds the standard warranty period (usually 12 months). Additionally, there are no photos provided to assess the damage.",
  "requiresFollowup": true,
  "followupQuestions": [
    "Could you please provide photos of the damaged item?",
    "Can you confirm the exact purchase date and the warranty period for this item?"
  ],
  "action": "request_photos"
}
